/// The spec files a task references: `imported`, the files its prompt imports
/// from, then those its reply's tool calls work on in `spec_dir` or the
/// reference files, each once, in the order first referenced.
pub fn collect(
    imported: &[PathBuf],
    parts: &[ReplyPart],
    project_dir: &Path,
    spec_dir: Option<&Path>,
) -> Vec<Referenced> {
    let reference_dir = project_dir.join(REFERENCE_DIR);
    let mut files: Vec<Referenced> = imported
        .iter()
        .map(|path| Referenced {
            path: path.clone(),
            edited: false,
        })
        .collect();
    for part in parts {
        let ReplyPart::Tool(call) = part else {
            continue;
        };
        let Some(summary) = call.summary.as_deref().filter(|_| call.works_on_a_file()) else {
            continue;
        };
        let path = project_dir.join(summary);
        let is_spec =
            spec_dir.is_some_and(|dir| path.starts_with(dir)) || path.starts_with(&reference_dir);
        if !is_spec {
            continue;
        }
        let edited = !matches!(call.name.as_str(), "Read" | "NotebookRead");
        match files.iter_mut().find(|file| file.path == path) {
            Some(file) => file.edited |= edited,
            None => files.push(Referenced { path, edited }),
        }
    }
    files
}

